import { MONSTER_DATA, MONSTER_ZONES } from "@hunt/hunt-data/monarch";
import {
  getLocalSolvedPuzzleMap,
  ShowAllPuzzmonInfoBox,
} from "@hunt/puzzle-components";
import { ConditionalTooltip } from "@hunt/shadcn";
import { useState } from "react";
import ElandIslandsMap from "./assets/ElandIslandsMap.png";
import { PUZZMON_POSITIONS, PUZZMON_IMAGES, type PuzzmonSlug } from "./data";

const MONARCH_QUERY_KEYS = {
  IS_OPEN: "showMonarch",
  ZONE: "zone",
  PUZZMON_SLUG: "puzzmonSlug",
} as const;

const ELAND_ISLANDS_ZONE = "eland_islands";
const elandIslandsPuzzmon = MONSTER_DATA[MONSTER_ZONES.ELAND_ISLANDS];

const updateQueryParam = (
  key: string,
  value: string,
  shouldReplace = false,
) => {
  if (typeof window === "undefined") {
    return;
  }
  const currentUrl = new URL(window.location.href);
  currentUrl.searchParams.set(key, value);
  if (shouldReplace) {
    window.history.replaceState({}, "", currentUrl.toString());
  } else {
    window.history.pushState({}, "", currentUrl.toString());
  }
};

const openMonarchForPuzzmon = (slug: string) => {
  updateQueryParam(MONARCH_QUERY_KEYS.IS_OPEN, "true");
  updateQueryParam(MONARCH_QUERY_KEYS.ZONE, ELAND_ISLANDS_ZONE, true);
  updateQueryParam(MONARCH_QUERY_KEYS.PUZZMON_SLUG, slug, true);
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent("monarch-open"));
  }
};

export type PuzzmonImage = {
  slug: string;
  name: string;
  image: string;
  top: number;
  left: number;
};

const getSolvedPuzzmon = (): PuzzmonSlug[] => {
  const localSolvedPuzzleMap = getLocalSolvedPuzzleMap();
  return Object.values(localSolvedPuzzleMap)
    .filter((entry): entry is { puzzmonSlug: PuzzmonSlug } =>
      Boolean(
        entry.puzzmonSlug &&
          entry.puzzmonSlug in elandIslandsPuzzmon &&
          entry.puzzmonSlug in PUZZMON_POSITIONS,
      ),
    )
    .map(({ puzzmonSlug }) => puzzmonSlug);
};

const getAllPuzzmonSlugs = (): PuzzmonSlug[] =>
  Object.keys(PUZZMON_POSITIONS) as PuzzmonSlug[];

export const DeerAirlinesMap = () => {
  const [showAllPuzzmon, setShowAllPuzzmon] = useState(false);

  const puzzmonSlugsToShow = showAllPuzzmon
    ? getAllPuzzmonSlugs()
    : getSolvedPuzzmon();

  const puzzmonImages = puzzmonSlugsToShow.map((puzzmonSlug) => ({
    slug: puzzmonSlug,
    name: puzzmonSlug.charAt(0).toUpperCase() + puzzmonSlug.slice(1),
    image: PUZZMON_IMAGES[puzzmonSlug],
    top: PUZZMON_POSITIONS[puzzmonSlug].top,
    left: PUZZMON_POSITIONS[puzzmonSlug].left,
  }));
  return (
    <>
      {(showAllPuzzmon ||
        puzzmonSlugsToShow.length !== getAllPuzzmonSlugs().length) && (
        <ShowAllPuzzmonInfoBox
          showAllPuzzmon={showAllPuzzmon}
          onToggle={() => {
            setShowAllPuzzmon(!showAllPuzzmon);
          }}
        />
      )}
      <div className="relative inline-block w-full">
        <img
          src={ElandIslandsMap}
          alt="Map of the Eland Islands"
          className="h-auto w-full rounded-lg border border-gray-200"
        />
        {puzzmonImages.map(({ slug, name, image, top, left }) => {
          return (
            <ConditionalTooltip key={slug} tooltip={name}>
              <button
                type="button"
                onClick={() => {
                  openMonarchForPuzzmon(slug);
                }}
                aria-label={`Show ${slug} in the MonArch window`}
                style={{
                  position: "absolute",
                  width: "16%",
                  maxWidth: "120px",
                  top: `${top}%`,
                  left: `${left}%`,
                  transform: "translate(-50%, -50%)",
                  display: "block",
                }}
                className="group block bg-transparent p-0 border-0 cursor-pointer focus-visible:outline-none"
              >
                <img
                  src={image}
                  alt={slug}
                  className="select-none transition-transform duration-150 ease-out group-hover:scale-110 group-focus-visible:scale-110 transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.5)]"
                  style={{
                    width: "100%",
                    height: "auto",
                  }}
                  draggable={false}
                />
              </button>
            </ConditionalTooltip>
          );
        })}
      </div>
    </>
  );
};
